PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  dc:   <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT  ?x
WHERE
  { <http://rdf.freebase.com/ns/m.081pw>
              <http://rdf.freebase.com/ns/time.event.start_date>  ?start ;
              <http://rdf.freebase.com/ns/time.event.end_date>  ?end .
    ?x        <http://rdf.freebase.com/ns/government.politician.government_positions_held>  ?y .
    ?y        <http://rdf.freebase.com/ns/government.government_position_held.office_position_or_title>  <http://rdf.freebase.com/ns/m.060d2> ;
              <http://rdf.freebase.com/ns/government.government_position_held.from>  ?from ;
              <http://rdf.freebase.com/ns/government.government_position_held.to>  ?to
    FILTER ( ?from < ?end )
    FILTER ( ?to > ?start )
      { FILTER EXISTS { ?y  <http://rdf.freebase.com/ns/government.government_position_held.from>  "1933-03-05"^^xsd:dateTime } }
    UNION
      { FILTER EXISTS { ?y  <http://rdf.freebase.com/ns/government.government_position_held.to>  "1933-12-31"^^xsd:dateTime } }
    UNION
      { FILTER ( ?from < "1939-01-02"^^xsd:dateTime ) }
  }

