                  <http://rdf.freebase.com/ns/film.performance.special_performance_type>  <http://rdf.freebase.com/ns/m.02nsjvf> .
        ?actor    <http://rdf.freebase.com/ns/film.actor.dubbing_performances>  ?dub1 .
        ?dub1     <http://rdf.freebase.com/ns/film.dubbing_performance.character>  <http://rdf.freebase.com/ns/g.121_h_cq>
